using DAO.Repositories.Portal; using Model.Ortak; using Model.Portal; using System; using System.Collections.Generic; using System.Data; using System.Linq;
namespace Model.Services.Portal { public class DuyuruOkumaService { private readonly DuyuruOkumaRepository r; public DuyuruOkumaService():this(new DuyuruOkumaRepository()){} public DuyuruOkumaService(DuyuruOkumaRepository r){if(r==null)throw new ArgumentNullException("r");this.r=r;} public DuyuruOkuma GetById(int id){return Map(r.SelectById(id));} public List<DuyuruOkuma> GetAll(){return List(r.SelectAll());} public int Save(DuyuruOkuma x){if(x==null)throw new ArgumentNullException("x");x.OlusturmaTarihi=DateTime.Now;x.Id=r.Insert(x);return x.Id;} public bool Update(DuyuruOkuma x){if(x==null||x.Id==0)return false;x.DegistirmeTarihi=DateTime.Now;return r.Update(x);} public bool Delete(DuyuruOkuma x){return x!=null&&x.Id!=0&&r.Delete(x.Id);} public string GetByDuyuruId(int id){return new DuyuruOkuma().ToJSON(r.SelectByDuyuruId(id));} private static List<DuyuruOkuma> List(DataTable t){return new DuyuruOkuma().ToList<DuyuruOkuma>(t);} private static DuyuruOkuma Map(DataTable t){return List(t).FirstOrDefault();} } }
